CREATE TABLE user_account(id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, failed_attempts INT DEFAULT 0, locked_until TIMESTAMP, is_active BOOLEAN DEFAULT TRUE NOT NULL);
CREATE TABLE membership_tier(id INT PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE, min_spending BIGINT NOT NULL, point_multiplier DECIMAL(3,2) NOT NULL, discount_percent INT NOT NULL);
CREATE TABLE customer(id INT PRIMARY KEY, tier_id INT NOT NULL, full_name VARCHAR(100) NOT NULL, phone VARCHAR(15) NOT NULL UNIQUE, point_balance INT DEFAULT 0 CHECK (point_balance >= 0), spending_12m BIGINT DEFAULT 0, is_new BOOLEAN DEFAULT TRUE NOT NULL, FOREIGN KEY (tier_id) REFERENCES membership_tier(id));
CREATE TABLE staff(id INT PRIMARY KEY, full_name VARCHAR(100) NOT NULL);
CREATE TABLE service(id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, price BIGINT NOT NULL CHECK (price >= 0), duration_min INT NOT NULL CHECK (duration_min > 0), is_active BOOLEAN DEFAULT TRUE, trial_percent INT DEFAULT 0 NOT NULL CHECK (trial_percent BETWEEN 0 AND 80));
CREATE TABLE staff_service(staff_id INT, service_id INT, PRIMARY KEY (staff_id, service_id), FOREIGN KEY (staff_id) REFERENCES staff(id), FOREIGN KEY (service_id) REFERENCES service(id));
CREATE TABLE room(id INT PRIMARY KEY, name VARCHAR(50) NOT NULL);
CREATE TABLE shift(id INT PRIMARY KEY, name VARCHAR(30) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL);
CREATE TABLE work_schedule(id INT AUTO_INCREMENT PRIMARY KEY, staff_id INT NOT NULL, work_date DATE NOT NULL, shift_id INT NOT NULL, UNIQUE (staff_id, work_date, shift_id), FOREIGN KEY (staff_id) REFERENCES staff(id), FOREIGN KEY (shift_id) REFERENCES shift(id));
CREATE TABLE combo(id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, discount_percent INT NOT NULL CHECK (discount_percent BETWEEN 30 AND 50), is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE combo_item(combo_id INT NOT NULL, service_id INT NOT NULL, PRIMARY KEY (combo_id, service_id), FOREIGN KEY (combo_id) REFERENCES combo(id), FOREIGN KEY (service_id) REFERENCES service(id));
CREATE TABLE service_package(id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, service_id INT NOT NULL, total_sessions INT NOT NULL CHECK (total_sessions > 0), price BIGINT NOT NULL CHECK (price >= 0), valid_days INT NOT NULL CHECK (valid_days > 0), FOREIGN KEY (service_id) REFERENCES service(id));
CREATE TABLE customer_package(id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, package_id INT NOT NULL, remaining_sessions INT NOT NULL CHECK (remaining_sessions >= 0), purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer(id), FOREIGN KEY (package_id) REFERENCES service_package(id));
CREATE TABLE appointment(id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, start_time TIMESTAMP NOT NULL, end_time TIMESTAMP NOT NULL, status VARCHAR(15) NOT NULL, cancel_reason VARCHAR(200), guest_count INT DEFAULT 1 NOT NULL CHECK (guest_count >= 1), combo_id INT, FOREIGN KEY (customer_id) REFERENCES customer(id), FOREIGN KEY (combo_id) REFERENCES combo(id));
CREATE TABLE appointment_service(id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, service_id INT NOT NULL, staff_id INT NOT NULL, room_id INT NOT NULL, start_time TIMESTAMP NOT NULL, end_time TIMESTAMP NOT NULL, price_at_booking BIGINT NOT NULL, customer_package_id INT, FOREIGN KEY (appointment_id) REFERENCES appointment(id), FOREIGN KEY (service_id) REFERENCES service(id), FOREIGN KEY (staff_id) REFERENCES staff(id), FOREIGN KEY (room_id) REFERENCES room(id), FOREIGN KEY (customer_package_id) REFERENCES customer_package(id));
CREATE TABLE invoice(id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT UNIQUE, customer_id INT NOT NULL, subtotal BIGINT NOT NULL, package_discount BIGINT DEFAULT 0 NOT NULL, promo_type VARCHAR(10), promo_discount BIGINT DEFAULT 0 NOT NULL, tier_discount BIGINT NOT NULL, point_discount BIGINT NOT NULL, total BIGINT NOT NULL, status VARCHAR(10) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (appointment_id) REFERENCES appointment(id), FOREIGN KEY (customer_id) REFERENCES customer(id));
CREATE TABLE payment(id INT AUTO_INCREMENT PRIMARY KEY, invoice_id INT NOT NULL, method VARCHAR(10) NOT NULL, amount BIGINT NOT NULL CHECK (amount > 0), paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (invoice_id) REFERENCES invoice(id));
CREATE TABLE loyalty_transaction(id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, invoice_id INT, type VARCHAR(10) NOT NULL, points INT NOT NULL, balance_after INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customer(id));
